package backlog

import (
	"fmt"
	"sort"
	"strings"
)

// Header is the index's first line: the "generated by <command>; do not edit"
// shape internal/clidoc's documents carry (D28). It names the command that
// writes the file, so a reader who finds a stale index has the one command
// that fixes it on the first line.
const Header = "<!-- generated by fugaro backlog index; do not edit -->"

// renderPreamble is what the index says about itself before its rows. Its two
// load-bearing sentences are D28's: the file is regenerated rather than
// edited, and two branches that regenerated it at once are reconciled by
// re-running the command rather than by merging it.
const renderPreamble = "One file per item, named `<id>-<slug>.md`, beside this one, and this index,\n" +
	"which is generated from them by `fugaro backlog index`. **Do not edit it:\n" +
	"regenerate it.** Two branches that regenerated it at once are reconciled by\n" +
	"re-running the command, never by merging the file, because it holds nothing a\n" +
	"reader cannot get back in one command (D28). The format an item follows is\n" +
	"[FORMAT.md](FORMAT.md); the ruling that made this folder is\n" +
	"[the rigor modes reconciliation](../rigor-modes/reconciliation.md) (D26–D32).\n"

// renderHeadings are the sections the rows are grouped under, in the order
// they appear: the open items, then the closed and the dropped ones grouped
// under them (D28).
var renderHeadings = []struct{ status, heading string }{
	{"open", "## Open"},
	{"closed", "## Closed"},
	{"dropped", "## Dropped"},
}

// renderColumns is the table's header row and separator: one row per item,
// with the id linked to its file (D28).
const renderColumns = "| id | title | mode | area | status | filed-by | date |\n" +
	"| --- | --- | --- | --- | --- | --- | --- |\n"

// Render returns the index the item files render to (D28): one row per item —
// the id linked to its file, the title, the mode, the area, the status, who
// filed it and the date — sorted by id, which is to say by date, plus a count
// line, with the closed and dropped rows grouped under the open ones.
//
// It is a pure function of its argument. Every date in the document comes
// from an item, and it reads no clock, no network and no environment, so two
// renders of one folder are the same bytes and a regeneration in review diffs
// only where an item changed (D27). The items are sorted here rather than
// trusted to be sorted, so a caller cannot change the document by handing the
// same items over in another order.
func Render(items []Item) string {
	sorted := make([]Item, len(items))
	copy(sorted, items)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })

	var b strings.Builder
	b.WriteString(Header + "\n\n")
	b.WriteString("# The backlog\n\n")
	b.WriteString(renderPreamble)
	b.WriteString("\n")
	b.WriteString(countLine(sorted) + "\n")

	if len(sorted) == 0 {
		b.WriteString("\nNo items yet.\n")
		return b.String()
	}
	for _, group := range renderHeadings {
		rows := rowsFor(sorted, group.status)
		if len(rows) == 0 {
			continue
		}
		b.WriteString("\n" + group.heading + "\n\n")
		b.WriteString(renderColumns)
		for _, it := range rows {
			fmt.Fprintf(&b, "| [%s](%s) | %s | %s | %s | %s | %s | %s |\n",
				it.ID, itemName(it.Path), cell(it.Title), cell(it.Mode), cell(it.Area),
				it.Status, cell(it.FiledBy), it.Date)
		}
	}
	return b.String()
}

// countLine is D28's count line. It is what tells a reader that a status with
// no section has no items rather than a section someone dropped: an empty
// group is not rendered at all, so the figure is the only place the zero is
// stated.
func countLine(items []Item) string {
	counts := map[string]int{}
	for _, it := range items {
		counts[it.Status]++
	}
	noun := "items"
	if len(items) == 1 {
		noun = "item"
	}
	return fmt.Sprintf("%d %s: %d open, %d closed, %d dropped.",
		len(items), noun, counts["open"], counts["closed"], counts["dropped"])
}

// rowsFor returns the items with one status, in id order.
func rowsFor(items []Item, status string) []Item {
	var out []Item
	for _, it := range items {
		if it.Status == status {
			out = append(out, it)
		}
	}
	return out
}

// cell makes text safe in a Markdown table cell: a pipe would end the row and
// a newline would end the table. An item's title and area are a filer's own
// words, so neither is trusted to be one line. A backslash is escaped before
// the pipe is, or a value's own backslash would escape the escape.
func cell(s string) string {
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\\", "\\\\")
	return strings.ReplaceAll(s, "|", "\\|")
}
